from pathlib import Path
import json,hashlib,datetime,subprocess,os
r=Path('.local/step07-review/independent-round13');sha=lambda b:hashlib.sha256(b).hexdigest()
def save(p,v):(r/p).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n')
canonical=Path('/Users/dingshinn/Desktop/rpg-maker-maker/docs/orchestration/steps-06-07-state.json');cb=canonical.read_bytes();cv=json.loads(cb);save('evidence/canonical-readonly-end.json',{'path':str(canonical),'sha256':sha(cb),'bytes':len(cb),'phase':cv['phase'],'currentStep':cv['currentStep'],'mainMayUpdateExternally':True,'writtenByReviewer':False})
# Preserve own diagnostic source as documentary JSON, never a runtime import.
out=r/'evidence/probes';out.mkdir(exist_ok=True)
for p in r.iterdir():
 if p.is_file() and p.suffix in ['.py','.mjs']:
  b=p.read_bytes();(out/(p.name+'.json')).write_text(json.dumps({'originalPath':p.name,'sha256':sha(b),'bytes':len(b),'purpose':'own ignored independent reviewer diagnostic source; no production/test/config import','documentarySource':b.decode()},ensure_ascii=False,indent=2)+'\n')
# Bind fixed test output without relocating DB-linked assets or deleting failures.
external=[]
for root in Path('.local').iterdir():
 if not root.is_dir() or root.name in ['postgres','step07-review']:continue
 for p in root.rglob('*'):
  if p.is_file() and not p.is_symlink():
   b=p.read_bytes();external.append({'originalPath':str(p),'bytes':len(b),'sha256':sha(b)})
externalPath=r/'private/retained-fixed-output-inventory.json';externalPath.write_text(json.dumps(external,indent=2)+'\n');save('evidence/fixed-output-retention.json',{'inventoryPath':str(externalPath.relative_to(r)),'bytes':externalPath.stat().st_size,'sha256':sha(externalPath.read_bytes()),'files':len(external),'operation':'RETAIN_ORIGINAL_PATHS_NO_MOVE_NO_DELETION','postgresNotInInventory':'active owned database is retained for Main; no page-file snapshot claim'})
public=[r/'report.md',r/'progress.json']+[p for p in (r/'evidence').rglob('*') if p.is_file() and p.name not in ['ledger.json','sensitive-scan.json']]
secret=json.loads(Path('.local/postgres/ownership.json').read_text())['password'].encode();env=Path('.env').read_bytes();dsn=next(x.split(b'=',1)[1] for x in env.splitlines() if x.startswith(b'DATABASE_URL='));hits=[]
for p in public:
 b=p.read_bytes()
 for label,value in [('own-password',secret),('own-DSN',dsn)]:
  if value and value in b:hits.append({'path':str(p.relative_to(r)),'type':label})
assert not hits,'Private credential byte scan failed (values withheld)'
save('evidence/sensitive-scan.json',{'scannedFiles':len(public),'ownPasswordHits':0,'ownDSNHits':0,'valuesReadOnlyInRAM':True,'secretValuesPrinted':False,'scanCovers':'report/progress and every public payload other than this scan record and ledger; both metadata contain no secret values','privateEnvOwnershipDumpRuntimeTraceExcluded':True})
public.append(r/'evidence/sensitive-scan.json');publicSet=set(p.resolve() for p in public);private=[]
for p in r.rglob('*'):
 if p.is_file() and not p.is_symlink() and p.resolve() not in publicSet and p.name!='ledger.json' and p!=r/'private/private-inventory.json':
  b=p.read_bytes();private.append({'path':str(p.relative_to(r)),'bytes':len(b),'sha256':sha(b)})
privatePath=r/'private/private-inventory.json';privatePath.write_text(json.dumps(private,indent=2)+'\n')
files={}
for p in sorted(public):
 b=p.read_bytes();files[str(p.relative_to(r))]={'sha256':sha(b),'bytes':len(b)}
